  function setBilling(yearly){
    m.setAttribute('aria-pressed', !yearly);
    y.setAttribute('aria-pressed', yearly);
    document.querySelectorAll('a[data-plan]').forEach(a=>{
      a.href = '/signup?plan=' + a.dataset.plan + (yearly && a.dataset.plan !== 'starter' ? '&billing=yearly' : '');
    });
    document.querySelectorAll('[data-m]').forEach(el=>{
      el.textContent = yearly ? el.dataset.y : el.dataset.m;
    });
  }
  m.onclick = ()=>setBilling(false);
  y.onclick = ()=>setBilling(true);

  const plans = document.getElementById('plans');
  const cards = plans.querySelectorAll('.plan');
  const fitBtns = document.querySelectorAll('#fit button');
  fitBtns.forEach(b=>b.onclick = ()=>{
    const on = b.getAttribute('aria-pressed') !== 'true';
    fitBtns.forEach(x=>x.setAttribute('aria-pressed','false'));
    cards.forEach(c=>c.classList.remove('fit'));
    plans.classList.toggle('has-fit', on);
    if(on){
      b.setAttribute('aria-pressed','true');
      cards[b.dataset.fit].classList.add('fit');
    }
  });
</script>
</body>
</html>

